void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float block = max(U.p0.x, 2.0);
    vec2 cell = (floor(fragCoord / block) + 0.5) * block / iResolution.xy;
    float m = smoothstep(0.08, 0.3, texture(iChannel1, cell).r);
    vec3 live = texture(iChannel0, uv).rgb;
    vec3 chunk = floor(texture(iChannel0, cell).rgb * 5.0 + 0.5) / 5.0;
    vec2 g = fract(fragCoord / block);
    chunk *= 0.85 + 0.15 * step(0.08, min(g.x, g.y));
    fragColor = vec4(mix(live, chunk, m), 1.0);
}
